def tone(frequency=440.0, seconds=0.1, sample_rate=16000):
    times = torch.arange(round(seconds * sample_rate)) / sample_rate
    return 0.5 * torch.sin(2 * math.pi * frequency * times)

def log_mel(waveform, sample_rate=16000, n_fft=400, hop_length=160, bands=16):
    if waveform.shape[-1] <= n_fft // 2:
        waveform = F.pad(waveform, (0, n_fft // 2 + 1 - waveform.shape[-1]))
    window = torch.hann_window(n_fft, device=waveform.device, dtype=waveform.dtype)
    spectrum = torch.stft(waveform, n_fft, hop_length, window=window, return_complex=True)
    power = spectrum.abs().square()
    bank = mel_filter_bank(sample_rate, n_fft, bands, waveform.device).to(power.dtype)
    return (bank @ power).clamp(min=1e-8).log()

class AudioEncoder(nn.Module):
    def __init__(self, bands=16, width=16):
        super().__init__()
        self.bands = bands
        self.projection = nn.Linear(bands, width)
        self.feature = nn.Sequential(nn.LayerNorm(width), nn.Linear(width, width), nn.GELU())

    def forward(self, waveform):
        features = log_mel(waveform, bands=self.bands).transpose(-1, -2)
        return self.feature(self.projection(features))

def _audio_records():
    splits = {}
    frequencies = {
        "train": (140, 180, 220, 260, 340, 380, 420, 460),
        "validation": (160, 240, 360, 440),
        "test": (200, 280, 290, 300, 310, 320, 400),
    }
    for split, values in frequencies.items():
        splits[split] = [
            {
                "modality": "audio",
                "frequency": f,
                "amplitude": amplitude,
                "seconds": seconds,
                "question": "pitch?",
                "answer": "high" if f > 300 else "low",
                "family": str(f),
            }
            for f in values
            for amplitude, seconds in ((0.25, 0.1), (0.5, 0.12))
        ]
    return splits

def _media(row, ctx):
    image = waveform = None
    if row["modality"] in ("vision", "joint"):
        if "image" in row:
            with Image.open(row["image"]) as source:
                pixels = np.array(source.convert("RGB").resize((16, 16)), copy=True)
            image = torch.from_numpy(pixels).permute(2, 0, 1).float() / 255
        elif "digits" in row:
            from scripts.prepare_ocr import draw_digits

            pixels = np.array(draw_digits(row["digits"], row["offset"]), copy=True)
            image = torch.from_numpy(pixels).permute(2, 0, 1).float() / 255
        else:
            image = scene(row["color"], row["shape"], offset=row["offset"])
    if row["modality"] in ("audio", "joint"):
        if "audio" in row:
            values, sample_rate = sf.read(row["audio"], dtype="float32")
            if values.ndim != 1 or not len(values):
                raise ValueError("錄音必須是非空單聲道")
            waveform = torch.from_numpy(values.copy())
            if sample_rate != 16000:
                raise ValueError("必須先真正重採樣為 16 kHz")
        else:
            waveform = tone(row["frequency"], seconds=row.get("seconds", 0.1)) * (row.get("amplitude", 0.5) / 0.5)
    return (None if image is None else image.to(ctx.device), None if waveform is None else waveform.to(ctx.device))

class ChatSession:
    """Keep actual replies and original modality messages across interactive turns."""

    def __init__(self, assistant, messages=None):
        self.assistant = assistant
        self.messages = copy.deepcopy(messages or [])

    def ask(self, content, *, task="text", **kwargs):
        pending = self.messages + [{"role": "user", "content": content}]
        result = self.assistant.reply(pending, task=task, **kwargs)
        self.messages = result["messages"]
        return result
